class Solution:
    def maxIceCream(self, costs: List[int], coins: int) -> int:
        maxCost = max(costs)
        count = [0] * (maxCost + 1)

        for cost in costs:
            count[cost] += 1
        ans = 0
        print(count)
        for i in range(len(count)):
            if coins <= 0:
                break
            if count[i] <= 0:
                continue
            while count[i] > 0 and coins >= i:
                coins -= i
                ans += 1
                count[i] -= 1

        return ans
